def require(ok,message):
 if not ok:raise RuntimeError(message)
def digest(raw):return {'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest()}
def write(path,value):path.write_text(json.dumps(value,indent=2)+'\n')
def module(name,path):
 spec=importlib.util.spec_from_file_location(name,path);m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m);return m
def instrument(original):
 text=original.decode()
 header="""import {writeSync as __psc1Write} from 'node:fs';
import {performance as __psc1Clock} from 'node:perf_hooks';
let __psc1Sequence=0,__psc1Command=0;
function __psc1Emit(row){__psc1Write(2,'PSC1_INGRESS_STAGE '+JSON.stringify({...row,milliseconds:__psc1Clock.now()},(_k,v)=>typeof v==='bigint'?v.toString():v)+'\\n');}
function __psc1Kind(value){return Object.getOwnPropertySymbols(value).map(key=>value[key]).find(item=>typeof item==='string')??'unknown';}
function __psc1Meta(command,arena,built){return {commandIndex:__psc1Command++,kind:__psc1Kind(command),requestKind:command.request?__psc1Kind(command.request):null,arenaNodes:arena.size,decodedNodes:built.size};}
function* __psc1Probe(stage,iterator,metadata={}){const id=++__psc1Sequence,start=__psc1Clock.now();__psc1Emit({phase:'begin',id,stage,...metadata});try{return yield* iterator;}finally{__psc1Emit({phase:'end',id,stage,...metadata,elapsedMilliseconds:__psc1Clock.now()-start});}}
"""
 replacements=[]
 def patch(function,old,label,metadata='{}'):
  nonlocal text
  start=text.index('function* __ps$impl$'+function+'(')
  end=text.index('\n__ps$implementations.set('+function+',',start)
  body=text[start:end]
  require(body.count(old)==1,'Single exact diagnostic call site: '+label)
  require(old.startswith('(yield* ') and old.endswith(')'),'Expected yield expression')
  new="(yield* __psc1Probe("+repr(label)+",(function* () { return "+old+"; })(),"+metadata+"))"
  text=text[:start]+body.replace(old,new)+text[end:]
  replacements.append({'function':function,'original':old,'instrumented':new,'stage':label})
 patch('psKernelV1RunDag','(yield* __ps$invoke(psKernelKernelSessionPreflight, session))','preflight')
 patch('psKernelV1RunDag','(yield* __ps$invoke(psKernelExprV2PagedValidate, source))','validation','{sourceNodes:source.size}')
 patch('psKernelV1RunDag','(yield* __ps$invoke((yield* __ps$invoke((yield* __ps$invoke((yield* __ps$invoke(psKernelExprV2DecodeCanonicalFuel, (canonical.size + 1n))), canonical)), psKernelExprV2DecodedEmpty)), 0n))','decode','{sourceNodes:canonical.size}')
 patch('psKernelDagRunSessionCommands','(yield* __ps$invoke(psKernelDagGeneratedFromSession, session, arena, built))','session-owner','{arenaNodes:arena.size,decodedNodes:built.size}')
 patch('psKernelDagRunCommandsWithSource','(yield* __ps$invoke(psKernelDagRunOwnedCommandWithSource, input, execution, levelParams, safety, arena, built, command))','command','__psc1Meta(command,arena,built)')
 patch('psKernelDagRunCommandsWithSource','(yield* __ps$invoke(psKernelDagGeneratedDemandRange, result.execution.session.environment, built.size, result.owner))','post-command-owner','{commandIndex:__psc1Command-1,arenaNodes:result.owner.arena.size,decodedNodes:result.owner.built.size}')
 patch('psKernelDagTryAdmitSimpleWithFuel','(yield* __ps$invoke(psKernelExprV2AdmissionCheckHeaderWithFuel, fuel, context, initial, plan.base, plan.typeRoot))','admission-header','{commandIndex:__psc1Command-1,fuel,typeRoot:plan.typeRoot}')
 patch('psKernelDagTryAdmitSimpleWithFuel','(yield* __ps$invoke(psKernelExprV2AdmissionPrepareBodyWithFuel, fuel, context, afterHeader, plan))','admission-prepare-body','{commandIndex:__psc1Command-1,fuel,typeRoot:plan.typeRoot}')
 patch('psKernelDagTryAdmitSimpleWithFuel','(yield* __ps$invoke(psKernelExprV2AdmissionCheckBodyWithFuel, fuel, context, prepared, plan.base, plan.typeRoot, body.fst, body.snd, plan.mismatch))','admission-body','{commandIndex:__psc1Command-1,fuel,typeRoot:plan.typeRoot,bodyRoot:body.snd}')
 patch('psKernelExprV2AdmissionCheckHeaderWithFuel','(yield* __ps$invoke(psKernelExprV2AdmissionStaticOnCanonical, state.whnf.arena, typeRoot, base.levelParams))','header-static','{commandIndex:__psc1Command-1,fuel,root:typeRoot}')
 patch('psKernelExprV2AdmissionCheckHeaderWithFuel','(yield* __ps$invoke(psKernelExprV2TryCheckStateWithFuel, fuel, context, state, typeRoot))','header-infer','{commandIndex:__psc1Command-1,fuel,root:typeRoot}')
 patch('psKernelExprV2AdmissionCheckHeaderWithFuel','(yield* __ps$invoke(psKernelExprV2AdmissionEnsureSortWithFuel, fuel, context, checked.fst, checked.snd))','header-sort','{commandIndex:__psc1Command-1,fuel,root:checked.snd}')
 patch('psKernelExprV2AdmissionCheckBodyWithFuel','(yield* __ps$invoke(psKernelExprV2AdmissionStaticOnCanonical, state.whnf.arena, bodyRoot, base.levelParams))','body-static','{commandIndex:__psc1Command-1,fuel,root:bodyRoot}')
 patch('psKernelExprV2AdmissionCheckBodyWithFuel','(yield* __ps$invoke(psKernelExprV2TryCheckStateWithFuel, fuel, context, state, bodyRoot))','body-infer','{commandIndex:__psc1Command-1,fuel,root:bodyRoot}')
 patch('psKernelExprV2AdmissionCheckBodyWithFuel','(yield* __ps$invoke((yield* __ps$invoke((yield* __ps$invoke((yield* __ps$invoke((yield* __ps$invoke(psKernelExprV2TryDefEqStateWithFuel, fuel)), context)), checked.fst)), checked.snd)), typeRoot))','body-final-defeq','{commandIndex:__psc1Command-1,fuel,left:checked.snd,right:typeRoot}')
 restored=text
 for row in reversed(replacements):
  require(restored.count(row['instrumented'])==1,'Unique reversible instrumentation')
  restored=restored.replace(row['instrumented'],row['original'])
 require(restored.encode()==original,'Exact whole original kernel restored after removing probes')
 return (header+text).encode(),replacements
def prepare(out,archive):
 out.mkdir(parents=True,exist_ok=False)
 require(hashlib.sha256(archive.read_bytes()).hexdigest()=='98a69742b538296c5f413d0527dfeef8c4d1815fe64b12c8623cd33de63bee0d','Original complete corpus archive')
 kernel=(ROOT/'dist/arena435/kernel.js').read_bytes()
 require(digest(kernel)=={'bytes':10319156,'sha256':KERNEL},'Exact authenticated current complete kernel')
 detached=out/'detached';detached.mkdir()
 (detached/'kernel.mjs').write_bytes(kernel)
 probe,replacements=instrument(kernel)
 (detached/'diagnostic-kernel.mjs').write_bytes(probe)
 driver=(ROOT/'scripts/pskernel-arena-replay.mjs').read_bytes()
 (detached/'pskernel-arena-replay.mjs').write_bytes(driver)
 oracle=module('ingress_oracle',ROOT/'scripts/pskernel-arena435-oracle.py')
 cases=oracle.read_archive(archive);inputs={}
 for label,(name,sha,body) in CASES.items():
  item,=[x for x in cases if x[1]==name]
  adapted,provenance=oracle.adapt_header(item[2])
  require(digest(adapted)['sha256']==sha and hashlib.sha256(adapted.partition(b'\n')[2]).hexdigest()==body,'Exact complete original body: '+label)
  (detached/(label+'.ndjson')).write_bytes(adapted)
  inputs[label]={'file':name,'input':digest(adapted),'bodySha256':body,'adaptation':provenance}
 paths=['psc1/scripts/pskernel-prelude-ingress-ci.py','psc1/scripts/pskernel-unary-arena-artifact.py',
  'psc1/scripts/pskernel-church-stage-ci.py','psc1/scripts/pskernel-arena-replay.mjs','psc1/scripts/pskernel-arena435-oracle.py',
  'psc1/packages/pskernel-core/src/Ps/KernelCore/API/Dag.lean',
  'psc1/packages/pskernel-core/src/Ps/KernelCore/Core/ExprV2/Decode.lean',
  '.github/workflows/psc1-pskernel-prelude-ingress.yml']
 snapshots=[]
 for path in paths:
  raw=(ROOT.parent/path).read_bytes();target=out/'sources'/path
  target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(raw);snapshots.append({'path':path,**digest(raw)})
 shutil.copyfile(pathlib.Path(os.environ['RUNNER_TEMP'])/'arena435-independent/kernel-provenance.json',out/'kernel-provenance.json')
 write(out/'source.json',{'schema':'psc1-prelude-ingress-source-v1','workflowSourceSha':os.environ['GITHUB_SHA'],
  'runId':os.environ['GITHUB_RUN_ID'],'attempt':os.environ['GITHUB_RUN_ATTEMPT'],'kernelSourceSha':SOURCE,
  'productionTree':TREE,'kernel':digest(kernel),'diagnosticKernel':digest(probe),'driver':digest(driver),
  'reversibleWholeKernelInstrumentation':True,'includesCurriedSetup':True,'patches':replacements,'inputs':inputs,'sourceSnapshots':snapshots,
  'diagnosticOnly':True,'nativeProbe':False,'productionChanged':False,'fullQualification':False})
 print('PSC1_PRELUDE_INGRESS_PREPARE: PASS exactBody=true exactQualifiedKernel=true reversibleInstrumentation=true')
def bounded(out,label,node,kernel,case):
 detached=out/'detached';start=time.monotonic();timed=False
 stdout=out/(label+'.stdout');stderr=out/(label+'.stderr');timing=out/(label+'.time')
 env=dict(os.environ,PATH='',NODE_OPTIONS='',LC_ALL='C')
 with stdout.open('wb') as o,stderr.open('wb') as e:
  p=subprocess.Popen(['/usr/bin/time','-f','peak_rss_kib=%M wall_seconds=%e exit_status=%x','-o',str(timing),
   node,'--max-old-space-size=2048','pskernel-arena-replay.mjs',kernel,case+'.ndjson'],
   cwd=detached,env=env,stdout=o,stderr=e,start_new_session=True)
  try:p.wait(timeout=60)
  except subprocess.TimeoutExpired:
   timed=True
   try:os.killpg(p.pid,signal.SIGKILL)
   except ProcessLookupError:pass
   p.wait()
 status={'timedOut':timed,'exitCode':p.returncode,'seconds':time.monotonic()-start,
  'stdout':digest(stdout.read_bytes()),'stderr':digest(stderr.read_bytes())}
 write(out/(label+'.status.json'),status)
 prefix='PSC1_ARENA_REPLAY '
 results=[json.loads(x[len(prefix):]) for x in stdout.read_text().splitlines() if x.startswith(prefix)]
 require((timed and p.returncode==-9 and not results) or (not timed and p.returncode==0 and len(results)==1),'Actual bounded terminal status: '+label)
 result=results[0] if results else {'verdict':'timeout','stage':'host-wall-time'}
 require(result['verdict']!='driver_error','No diagnostic driver error: '+label)
 if not timed:require(result['sourceSha256']==CASES[case][1] and result['fuel']=='4096','Actual result identity and fuel')
 rows=[json.loads(x[len('PSC1_INGRESS_STAGE '):]) for x in stderr.read_text().splitlines() if x.startswith('PSC1_INGRESS_STAGE ')]
 open_stages={};complete=[]
 for row in rows:
  require(row['phase'] in ['begin','end'] and isinstance(row['id'],int),'Valid actual stage row')
  if row['phase']=='begin':
   require(row['id'] not in open_stages,'Unique actual begin')
   open_stages[row['id']]=row
  else:
   begin=open_stages.pop(row['id'])
   require(begin['stage']==row['stage'] and row['elapsedMilliseconds']>=0,'Matching actual stage end')
   complete.append(row)
 return {'status':status,'result':result,'stageRows':rows,'completeStages':complete,'openStages':list(open_stages.values())}
def execute(out,node):
 require(pathlib.Path(node).is_absolute(),'Absolute Node runtime')
 results={}
 for case in ['church','prelude']:
  for mode,kernel in [('baseline','kernel.mjs'),('stages','diagnostic-kernel.mjs')]:
   label=case+'-'+mode;results[label]=bounded(out,label,node,kernel,case)
 for mode in ['baseline','stages']:
  r=results['church-'+mode]['result']
  require(r['verdict']=='accepted' and r.get('metadataValidated') is True,'Independent accepted original Church sentinel: '+mode)
  require(not results['church-'+mode]['openStages'],'Church diagnostics complete')
 for case in ['church','prelude']:
  require(results[case+'-baseline']['result']['verdict']==results[case+'-stages']['result']['verdict'],'Actual public/diagnostic outcome agreement: '+case)
  stages=results[case+'-stages']
  require(stages['stageRows'] and [r['stage'] for r in stages['stageRows'][:5]]==['preflight','preflight','validation','validation','decode'],'Actual ordered ingress stages')
 last=results['prelude-stages']
 report={'schema':'psc1-prelude-ingress-diagnosis-v1','workflowSourceSha':os.environ['GITHUB_SHA'],
  'runId':os.environ['GITHUB_RUN_ID'],'attempt':os.environ['GITHUB_RUN_ATTEMPT'],'kernelSourceSha':SOURCE,
  'status':'pass','fuel':4096,'wallSeconds':60,'nodeOldSpaceMiB':2048,'emptyPATH':True,
  'diagnosticOnly':True,'nativeProbe':False,'productionChanged':False,'performanceQualified':False,
  'lastPreludeStage':last['stageRows'][-1] if last['stageRows'] else None,
  'preludeOpenStages':last['openStages'],'results':results}
 write(out/'report.json',report)
 print('PSC1_PRELUDE_INGRESS_DIAGNOSIS: PASS '+json.dumps({k:v for k,v in report.items() if k!='results'},separators=(',',':')))
if __name__=='__main__':
 require(os.environ.get('GITHUB_ACTIONS')=='true' and os.environ.get('RUNNER_OS')=='Linux','GitHub Linux only')
 p=argparse.ArgumentParser();p.add_argument('command',choices=['prepare','execute']);p.add_argument('--out',type=pathlib.Path,required=True)
 p.add_argument('--archive',type=pathlib.Path);p.add_argument('--node');a=p.parse_args()
 if a.command=='prepare':prepare(a.out.resolve(),a.archive.resolve())
 else:execute(a.out.resolve(),a.node)
